var tijmenvangulik_examples_historywidget;
(function (tijmenvangulik_examples_historywidget) {
    class HistoryXasOptions {
        static getFromId(id) {
            switch (id) //should learn too loop items in class
             {
                case "historyExampleTime": return HistoryXasOptions.workTime;
                case "historyExampleMeters": return HistoryXasOptions.distance;
                default: return HistoryXasOptions.workTime;
            }
        }
    }
    HistoryXasOptions.workTime = { value: "workTime", controlId: "historyExampleTime", chartAxisType: "datetime", caption: "Work time" };
    HistoryXasOptions.distance = { value: "distance", controlId: "historyExampleMeters", chartAxisType: "linear", caption: "Work distance" };
    tijmenvangulik_examples_historywidget.HistoryXasOptions = HistoryXasOptions;
    class HistoryYasOptions {
        static getFromId(id) {
            switch (id) //should learn too loop items in class
             {
                case "historyExampleSplit": return HistoryYasOptions.split;
                case "historyExamplePower": return HistoryYasOptions.power;
                case "historyExampleStrokesPerMinute": return HistoryYasOptions.strokesPerMinute;
                case "historyExampleHeartRate": return HistoryYasOptions.heartRate;
                case "historyExampleNone": return HistoryYasOptions.none;
                default: return HistoryYasOptions.split;
            }
        }
    }
    HistoryYasOptions.split = { value: "splitTime", controlId: "historyExampleSplit", chartAxisType: "datetime", caption: "Split time" };
    HistoryYasOptions.power = { value: "power", controlId: "historyExamplePower", chartAxisType: "linear", caption: "Power" };
    HistoryYasOptions.strokesPerMinute = { value: "strokesPerMinute", controlId: "historyExampleStrokesPerMinute", chartAxisType: "linear", caption: "Strokes per minute" };
    HistoryYasOptions.heartRate = { value: "heartRate", controlId: "historyExampleHeartRate", chartAxisType: "linear", caption: "Heart rate" };
    HistoryYasOptions.none = { value: "none", controlId: "historyExampleNone", chartAxisType: "", caption: "" };
    tijmenvangulik_examples_historywidget.HistoryYasOptions = HistoryYasOptions;
    // set up the updating of the chart each second
    class ExampleHistoryChartWidget extends ergometerWidgets.HighChartWidget {
        getHistorySettings() {
            return {
                xAxis: this._historyXasOption.controlId,
                yAxis: this._historyYasOption.controlId,
                yAxis2: this._historyYasOption2.controlId,
                historyYAxisStartZero: this._historyYAxisStartZero
            };
        }
        setHistorySettings(settings) {
            this._historyXasOption = HistoryXasOptions.getFromId(settings.xAxis);
            this._historyYasOption = HistoryYasOptions.getFromId(settings.yAxis);
            this._historyYasOption2 = HistoryYasOptions.getFromId(settings.yAxis2);
            this._historyYAxisStartZero = settings.historyYAxisStartZero === true;
        }
        saveHistoryState() {
            localStorage.setItem("historyExampleChartWidget_settings", JSON.stringify(this.getHistorySettings()));
        }
        loadHistoryState() {
            var settingsString = localStorage.getItem("historyExampleChartWidget_settings");
            var settings;
            if (settingsString != "undefined" && settingsString != null && settingsString != "null") {
                settings = JSON.parse(settingsString);
                this.setHistorySettings(settings);
            }
        }
        getChartOptions() {
            Highcharts.setOptions({
                global: {
                    useUTC: true
                }
            });
            var chartWidget = this;
            return {
                chart: {
                    renderTo: 'container',
                    type: 'area'
                    //	                zoomType: 'x',
                    //	                marginRight: 10,
                    //	                reflow: true
                },
                title: null,
                xAxis: {
                    type: this._historyXasOption.chartAxisType,
                    title: {
                        text: this._historyXasOption.caption
                    },
                    showFirstLabel: false
                },
                yAxis: [{
                        title: {
                            text: this._historyYasOption.caption
                        },
                        type: this._historyYasOption.chartAxisType
                    }, {
                        title: {
                            text: this._historyYasOption2.caption
                        },
                        type: this._historyYasOption2.chartAxisType,
                        opposite: true
                    }],
                plotOptions: {
                    area: {
                        marker: {
                            enabled: false,
                            states: {
                                hover: {
                                    enabled: true,
                                    radius: 5
                                }
                            }
                        },
                        threshold: (this._historyYAxisStartZero) ? 0 : null
                    }
                },
                tooltip: {
                    formatter: function () {
                        var x = this.x;
                        if (chartWidget._historyXasOption.chartAxisType == 'datetime')
                            x = Highcharts.dateFormat('%H:%M:%S', x);
                        var y = this.y;
                        var yAxis = chartWidget._historyYasOption;
                        if (this.series.index == 1)
                            yAxis = chartWidget._historyYasOption2;
                        if (yAxis.chartAxisType == 'datetime')
                            y = Highcharts.dateFormat('%M:%S', y);
                        return '<b>' + this.series.name + '</b><br/>' +
                            chartWidget._historyXasOption.caption + ':' + x + '<br/>' +
                            yAxis.caption + ':' + y;
                    }
                },
                legend: {
                    enabled: false
                },
                exporting: {
                    enabled: true
                },
                series: [{
                        name: 'History data',
                        data: [],
                        yAxis: 0
                    }, {
                        name: 'History data2',
                        data: [],
                        yAxis: 1
                    }]
            };
        }
        exportData() {
            if (pm3.monitor.historyCount > 0) {
                let exportData = [];
                for (let i = 0; i < pm3.monitor.historyCount; i++) {
                    let c = pm3.monitor.getHistory(i);
                    exportData.push({ "workTime": utilities.formatRelativeTime(c.workTime),
                        "power": c.power,
                        "strokesPerMinute": c.strokesPerMinute,
                        "distance": c.distance,
                        "splitTime": utilities.formatRelativeTime(c.splitTime),
                        "heartRate": c.heartRate
                    });
                }
                let sCSV = utilities.convertArrayOfObjectsToCSV({ data: exportData });
                let blob = new Blob([sCSV], { type: "data:application/json;charset=utf-8" });
                utilities.writeFile(blob, "History.csv");
            }
            else
                app.showTopError("No data to export.");
        }
        constructor(controller) {
            super(controller);
            this._historyXasOption = HistoryXasOptions.workTime;
            this._historyYasOption = HistoryYasOptions.split;
            this._historyYasOption2 = HistoryYasOptions.none;
            this._historyYAxisStartZero = true;
            this.editPropertiesVisible = true;
            this.defaultWidth = 3;
        }
        initEditPropertiesControls(done) {
            var widget = this;
            this._dialogHistorySettings = dialog.newStandardDialog({
                title: 'History example settings',
                message: $('#dialogHistoryExampleSettings'),
                onhide: () => {
                    widget.setOptions();
                    widget.reCreateChart();
                    widget.updateChart();
                },
                buttons: [{
                        label: 'Clear data',
                        action: (dlg) => {
                            widget.setOptions();
                            pm3.monitor.clearHistory();
                            widget.reCreateChart();
                            widget.updateChart();
                            dlg.close();
                        }
                    }, {
                        label: 'Export',
                        action: (dlg) => {
                            widget.exportData();
                        }
                    }
                ]
            });
            done();
        }
        setOptions() {
            var checkedControlIdX = $('input[name=radioHistoryExampleXAxis]:checked').prop('id');
            this._historyXasOption = HistoryXasOptions.getFromId(checkedControlIdX);
            var checkedControlIdY = $('input[name=radioHistoryExampleYAxis]:checked').prop('id');
            this._historyYasOption = HistoryYasOptions.getFromId(checkedControlIdY);
            var checkedControlIdY2 = $('input[name=radioHistoryExampleYAxis2]:checked').prop('id') || "historyExampleNone2";
            checkedControlIdY2 = checkedControlIdY2.replace('2', '');
            this._historyYasOption2 = HistoryYasOptions.getFromId(checkedControlIdY2);
            this._historyYAxisStartZero = $('#historyExampleYAxisStartZero').prop('checked');
            this.saveHistoryState();
        }
        openEditProperties() {
            //prop, not attr: attr only sets the initial state, not the state after the user has clicked
            $('#' + this._historyXasOption.controlId).prop('checked', true);
            $('#' + this._historyYasOption.controlId).prop('checked', true);
            $('#' + this._historyYasOption2.controlId + '2').prop('checked', true);
            $('#historyExampleYAxisStartZero').prop('checked', this._historyYAxisStartZero);
            this._dialogHistorySettings.open();
        }
        fillSeries(series, yOption) {
            var count = pm3.monitor.historyCount;
            var countPoints = series.points.length;
            var clear = false;
            //var date = new Date();
            //date = new Date(date.getFullYear(),date.getMonth(),date.getDay());
            if (count > countPoints) {
                for (var i = countPoints; i < count; i++) {
                    var last = (i == (count - 1));
                    var yValue = pm3.monitor.getHistory(i)[yOption.value];
                    var xValue = pm3.monitor.getHistory(i)[this._historyXasOption.value];
                    if (i > 0) {
                        var xPrevValue = pm3.monitor.getHistory(i - 1)[this._historyXasOption.value];
                        if (xPrevValue > xValue) //when time or meters go backwards, do a clear
                            clear = true;
                    }
                    if (xValue instanceof Date)
                        xValue = xValue.getTime(); //date.getTime()+
                    if (yValue instanceof Date)
                        yValue = yValue.getTime(); //date.getTime()+
                    series.addPoint([xValue, yValue], last, false);
                }
            }
            else if (count < countPoints)
                clear = true;
            return clear;
        }
        updateChart() {
            var clear = this.fillSeries(this.chart.series[0], this._historyYasOption);
            if (this._historyYasOption2 != HistoryYasOptions.none) {
                this.fillSeries(this.chart.series[1], this._historyYasOption2);
            }
            if (clear) {
                pm3.monitor.clearHistory();
                this.reCreateChart();
            }
        }
        historyUpdate(count) {
            this.updateChart();
        }
        loaded() {
            this.loadHistoryState();
            super.loaded();
            pm3.monitor.pubsubs.subHistoryUpdate(this, this.historyUpdate);
        }
        beforeUnload() {
            super.beforeUnload();
            pm3.monitor.pubsubs.unsubHistoryUpdate(this, this.historyUpdate);
        }
    }
    tijmenvangulik_examples_historywidget.ExampleHistoryChartWidget = ExampleHistoryChartWidget;
    /*------------------------------------------------------------------------------
        Create and remove the widgets in the Plugin
    ------------------------------------------------------------------------------*/
    class ExamplePlugin extends ExternalPlugin {
        init() {
            //create the widget(s) on create
            dashboard.widgetRegistry().register(ExampleHistoryChartWidget, 'tijmenvangulik_examples_HistoryWidget', 'History example chart', ['Examples']);
        }
        remove() {
            //remove the widgets when the plugin is removed
            dashboard.widgetRegistry().deregister('tijmenvangulik_examples_HistoryWidget');
        }
    }
    var plugin;
    plugin = new ExamplePlugin();
})(tijmenvangulik_examples_historywidget || (tijmenvangulik_examples_historywidget = {}));

