namespace tijmenvangulik_examples_historywidget { //make a name space to prevent mix ups

  interface  HistoryChartSettings {
    xAxis? : string;
    yAxis : string;
    yAxis2 : string;
    historyYAxisStartZero: boolean;
  }
  export interface HistoryXasOption {
    value : string;
    controlId : string;
    chartAxisType : string;
    caption : string;
  }
  export interface HistoryYasOption {
    value :string;
    controlId : string;
    chartAxisType : string;
    caption : string;
  }

  export class HistoryXasOptions{
    public static workTime : HistoryXasOption = {value : "workTime", controlId :"historyExampleTime",chartAxisType:"datetime", caption:"Work time" };
    public static distance : HistoryXasOption = {value :"distance" , controlId :"historyExampleMeters",chartAxisType:"linear",caption:"Work distance" };
    public static getFromId(id : string) : HistoryXasOption {
      switch (id) //should learn too loop items in class
      {
        case "historyExampleTime" : return HistoryXasOptions.workTime;
        case "historyExampleMeters" : return HistoryXasOptions.distance;
        default : return HistoryXasOptions.workTime;
      }

    }
  }

  export class HistoryYasOptions{
    public static split : HistoryYasOption= {value :"splitTime", controlId :"historyExampleSplit",chartAxisType:"datetime", caption:"Split time" };
    public static power : HistoryYasOption= {value :"power", controlId :"historyExamplePower",chartAxisType:"linear", caption:"Power" };
    public static strokesPerMinute : HistoryYasOption= {value :"strokesPerMinute", controlId :"historyExampleStrokesPerMinute",chartAxisType:"linear", caption:"Strokes per minute"};
    public static heartRate : HistoryYasOption= {value :"heartRate", controlId :"historyExampleHeartRate",chartAxisType:"linear", caption:"Heart rate" };
    public static none : HistoryYasOption= {value :"none", controlId :"historyExampleNone",chartAxisType:"", caption:"" };

    public static getFromId(id : string) : HistoryYasOption {
      switch (id) //should learn too loop items in class
      {
        case "historyExampleSplit" : return HistoryYasOptions.split;
        case "historyExamplePower" : return HistoryYasOptions.power;
        case "historyExampleStrokesPerMinute" : return HistoryYasOptions.strokesPerMinute;
        case "historyExampleHeartRate" : return HistoryYasOptions.heartRate;
        case "historyExampleNone" : return HistoryYasOptions.none;
        default : return HistoryYasOptions.split;
      }

    }

  }

// set up the updating of the chart each second


  export class ExampleHistoryChartWidget  extends ergometerWidgets.HighChartWidget {

    private _historyXasOption : HistoryXasOption = HistoryXasOptions.workTime;
    private _historyYasOption : HistoryYasOption = HistoryYasOptions.split;
    private _historyYasOption2 : HistoryYasOption = HistoryYasOptions.none;
    private _historyYAxisStartZero : boolean =true;

    private getHistorySettings() : HistoryChartSettings {
      return {
        xAxis: this._historyXasOption.controlId,
        yAxis: this._historyYasOption.controlId,
        yAxis2: this._historyYasOption2.controlId,
        historyYAxisStartZero: this._historyYAxisStartZero
      }
    }
    private setHistorySettings(settings : HistoryChartSettings) {
      this._historyXasOption=  HistoryXasOptions.getFromId(settings.xAxis);
      this._historyYasOption=  HistoryYasOptions.getFromId(settings.yAxis);
      this._historyYasOption2=  HistoryYasOptions.getFromId(settings.yAxis2);
      this._historyYAxisStartZero= settings.historyYAxisStartZero===true;
    }

    private saveHistoryState() {
      localStorage.setItem("historyExampleChartWidget_settings",JSON.stringify(this.getHistorySettings() ));
    }
    private loadHistoryState() {
      var settingsString=localStorage.getItem("historyExampleChartWidget_settings");
      var settings : HistoryChartSettings;
      if  (settingsString!="undefined" && settingsString!=null && settingsString!="null"  ) {
        settings=<HistoryChartSettings> JSON.parse(settingsString);
        this.setHistorySettings(settings);
      }
    }

    public getChartOptions() : HighchartsOptions {
      Highcharts.setOptions({
        global: {
          useUTC: true
        }
      });
      var chartWidget =this;
      return {
        chart: {
          renderTo: 'container',
          type: 'area'

//	                zoomType: 'x',
//	                marginRight: 10,
//	                reflow: true
        },
        title: null,
        xAxis: {
          type: this._historyXasOption.chartAxisType,
          title: {
            text: this._historyXasOption.caption
          },
          showFirstLabel: false

        },
        yAxis: [{
          title: {
            text: this._historyYasOption.caption
          },
          type: this._historyYasOption.chartAxisType
        },{
          title: {
            text: this._historyYasOption2.caption
          },
          type: this._historyYasOption2.chartAxisType,
          opposite:true
        }],
        plotOptions: {
          area: {
            marker: {
              enabled: false,
              states: {
                hover: {
                  enabled: true,
                  radius: 5
                }
              }
            },
            threshold: (this._historyYAxisStartZero)?0:null
          }
        },
        tooltip: {
          formatter: function() { //need mixed scope here
            var x : any=this.x;
            if (chartWidget._historyXasOption.chartAxisType=='datetime')
              x=Highcharts.dateFormat('%H:%M:%S', x);
            var y: any=this.y;
            var yAxis= chartWidget._historyYasOption;
            if (this.series.index==1) yAxis=chartWidget._historyYasOption2;
            if (yAxis.chartAxisType=='datetime')
              y=Highcharts.dateFormat('%M:%S', y)
            return '<b>'+ this.series.name +'</b><br/>'+
                chartWidget._historyXasOption.caption+':'+x+'<br/>'+
                yAxis.caption+':'+y;
          }
        },
        legend: {
          enabled: false
        },
        exporting: {
          enabled: true
        },
        series: [{
          name: 'History data',
          data: [ ],
          yAxis:0
        },{
          name: 'History data2',
          data: [ ],
          yAxis:1
        }]

      };
    }
    public exportData() {
      if (pm3.monitor.historyCount>0) {
        let exportData = [];
        for(let i =0; i<pm3.monitor.historyCount;i++ ) {
          let c=pm3.monitor.getHistory(i);
          exportData.push(
              { "workTime": utilities.formatRelativeTime(c.workTime),
                "power": c.power,
                "strokesPerMinute":c.strokesPerMinute ,
                "distance":c.distance,
                "splitTime":utilities.formatRelativeTime(c.splitTime),
                "heartRate":c.heartRate
              })
        }
        let sCSV = utilities.convertArrayOfObjectsToCSV({data: exportData});
        let blob = new Blob([sCSV], {type: "data:application/json;charset=utf-8"});

        utilities.writeFile(blob, "History.csv");
      }
      else app.showTopError("No data to export.")
    }

    constructor (controller : dashboard.Controller) {
      super(controller);
      this.editPropertiesVisible = true;
      this.defaultWidth=3;
    }
    private _dialogHistorySettings  : BootstrapDialog;
    public  initEditPropertiesControls(done : ()=>void) {


        var widget = this;
        this._dialogHistorySettings= dialog.newStandardDialog({
          title: 'History example settings',
          message: $('#dialogHistoryExampleSettings'),
          onhide: ()=>{
            widget.setOptions();
            widget.reCreateChart();
            widget.updateChart();
          },
          buttons:[ {
            label:'Clear data',
            action: (dlg)=>{
              widget.setOptions();
              pm3.monitor.clearHistory();
              widget.reCreateChart();
              widget.updateChart();
              dlg.close();
            }},{
            label:'Export',
            action: (dlg)=>{
              widget.exportData();
            }
          }

          ]
